import java.util.*;
class ArrayListOps {
    public ArrayList<Integer> convertArrayListtoInt(int n)
    {
        ArrayList<Integer> list = new ArrayList<Integer>();
        for(int i=0; i<n; i++)
            list.add(0);
        return list;
    }
    public  ArrayList<Integer> reverse(ArrayList<Integer> list) {
        ArrayList<Integer> b = new ArrayList<Integer>();
        for (int i = list.size() - 1; i >= 0; i--)
            b.add(list.get(i));
        return b;
    }
}

import java.util.*;
import java.util.function.*;
import java.util.stream.Stream;
class Employee {
    String name;
    int salary;
    Employee(String n, int s) {
        this.name = n;
        this.salary = s;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder("<");
        sb.append("name: ");
        sb.append(name);
        sb.append(" salary: ");
        sb.append("" + salary+">");
        return sb.toString();

    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public int getSalary() {
        return salary;
    }

    public void setSalary(int salary) {
        this.salary = salary;
    }
}
class EmployeeInfo{
    enum SortMethod {BYNAME, BYSALARY};
    Function<Employee, String> byName = e -> e.getName();
    Function<Employee, Integer> bySalary = e -> e.getSalary();

    public List<Employee> sort(List<Employee> emps, final SortMethod method) {
        if(method == SortMethod.BYNAME) {
            Collections.sort(emps, Comparator.comparing(byName).thenComparing(bySalary));
        } else {
            Collections.sort(emps, Comparator.comparing(bySalary).thenComparing(byName));
        }
        return emps;
    }
    // public Employee getThirdInCollection(Collection<Employee> entities) {
    //     return entities.stream().skip(2).findFirst().get();
    // }
    public boolean isCharacterPresentInAllNames(Collection<Employee> entities, String character)
    {
        return entities.stream().allMatch((s) -> s.getName().toLowerCase().contains(character.toLowerCase()));
    }
}

